-- 批量更新上次盘点日期
UPDATE asset_info SET last_inventory_date = iod.last_modified_date FROM( SELECT t1.asset_id, t1.last_modified_date FROM inventory_order_detail t1 INNER JOIN ( SELECT asset_id, MAX ( last_modified_date) last_modified_date FROM inventory_order_detail where status = 1 GROUP BY asset_id ) t2 ON t1.last_modified_date = t2.last_modified_date AND t1.asset_id = t2.asset_id ) iod WHERE asset_info.ID = iod.asset_id